/**
 * The op-graph: a serializable tree of modeling operations.
 *
 * The authoring API (api.ts) builds one of these; a Kernel (kernel.ts)
 * evaluates it into geometry. Nothing here computes geometry, which is what
 * lets us swap the mesh/CSG kernel for a Rust B-rep kernel later without
 * touching the editor, viewport, or authoring surface.
 *
 * `OpNode` is the single-source contract defined in `schema/opgraph.odk.yaml`
 * and generated by ODK into `opgraph.gen.ts`; this module re-exports it so the
 * same contract backs the TypeScript app and the Rust/WASM kernel. Regenerate
 * with `bun opgraph:generate`. `Vec3` is a local alias for the fixed-length
 * triple ODK emits inline, kept for the authoring API and callers.
 */

export type { OpNode } from "./opgraph.gen";

export type Vec3 = [number, number, number];
